{"source":"def validate_batch(batch):
    if not isinstance(batch, list):
        return {"ok": False, "error": "batch must be a list"}
    valid = []
    errors = []
    index = 0
    for element in batch:
        result = normalize_submission(element)
        if result["ok"]:
            valid.append(result["record"])
        else:
            errors.append({"index": index, "error": result["error"]})
        index = index + 1
    counts = {"total": len(batch), "valid": len(valid), "invalid": len(errors)}
    return {"ok": True, "valid": valid, "errors": errors, "counts": counts}"}

{"source":"def group_submissions(batch):
    checked = validate_batch(batch)
    if not checked["ok"]:
        return checked
    groups = {}
    for record in checked["valid"]:
        key = record["assignment"]
        if key not in groups:
            groups[key] = []
        groups[key].append(record)
    return {"ok": True, "groups": groups, "errors": checked["errors"]}"}

{"source":"def summarize_class(batch):
    checked = group_submissions(batch)
    if not checked["ok"]:
        return checked
    assignments = {}
    total_submissions = 0
    total_score = 0.0
    all_students = []
    for name in checked["groups"]:
        best = {}
        for record in checked["groups"][name]:
            student = record["student"]
            if student not in best or record["score"] > best[student]:
                best[student] = record["score"]
        count = 0
        group_total = 0.0
        for student in best:
            count = count + 1
            group_total = group_total + best[student]
            if student not in all_students:
                all_students.append(student)
        assignments[name] = {"submissions": count, "students": len(best), "average": round(group_total / count, 1)}
        total_submissions = total_submissions + count
        total_score = total_score + group_total
    if total_submissions == 0:
        overall_average = None
    else:
        overall_average = round(total_score / total_submissions, 1)
    overall = {"submissions": total_submissions, "students": len(all_students), "average": overall_average}
    return {"ok": True, "assignments": assignments, "overall": overall, "errors": checked["errors"]}"}

{"source":"def normalize_tracklist(payload):
    if not isinstance(payload, dict):
        return {"ok": False, "error": "payload must be an object with a 'tracks' list"}
    allowed = ["tracks", "allow_duplicates"]
    for key in sorted(payload):
        if key not in allowed:
            return {"ok": False, "error": "unexpected key '" + str(key) + "'"}
    if "tracks" not in payload or not isinstance(payload["tracks"], list):
        return {"ok": False, "error": "payload must be an object with a 'tracks' list"}
    allow_duplicates = False
    if "allow_duplicates" in payload:
        flag = payload["allow_duplicates"]
        if not isinstance(flag, bool):
            return {"ok": False, "error": "'allow_duplicates' must be a boolean when present"}
        allow_duplicates = flag
    tracks = []
    index = 0
    for entry in payload["tracks"]:
        parsed = parse_track(entry)
        if not parsed["ok"]:
            return {"ok": False, "error": "track " + str(index + 1) + ": " + parsed["error"]}
        tracks.append(parsed["track"])
        index = index + 1
    if not allow_duplicates:
        seen = []
        position = 0
        for track in tracks:
            pair = (track["artist"].lower(), track["title"].lower())
            if pair in seen:
                return {"ok": False, "error": "duplicate track " + str(position + 1)}
            seen.append(pair)
            position = position + 1
    output_tracks = []
    number = 0
    for track in tracks:
        number = number + 1
        if number < 10:
            track_id = "T0" + str(number)
        else:
            track_id = "T" + str(number)
        output_tracks.append({"id": track_id, "title": track["title"], "artist": track["artist"], "seconds": track["seconds"], "explicit": track["explicit"], "clock": format_clock(track["seconds"])})
    total = 0
    for track in tracks:
        total = total + track["seconds"]
    return {"ok": True, "count": len(tracks), "total_seconds": total, "total_clock": format_clock(total), "tracks": output_tracks}"}

{"source":"def sequence_playlist(payload):
    if not isinstance(payload, dict):
        return normalize_tracklist(payload)
    allowed = ["tracks", "order", "allow_duplicates"]
    for key in sorted(payload):
        if key not in allowed:
            return {"ok": False, "error": "unexpected key '" + str(key) + "'"}
    order = "artist"
    if "order" in payload:
        order = payload["order"]
        if order != "artist" and order != "duration":
            return {"ok": False, "error": "'order' must be 'artist' or 'duration'"}
    sub = {"tracks": payload["tracks"] if "tracks" in payload else None}
    if "allow_duplicates" in payload:
        sub["allow_duplicates"] = payload["allow_duplicates"]
    base = normalize_tracklist(sub)
    if not base["ok"]:
        return base
    tracks = base["tracks"]
    if order == "artist":
        ordered = sorted(tracks, key=lambda t: t["artist"].lower())
    else:
        ordered = sorted(tracks, key=lambda t: t["seconds"])
    return {"ok": True, "order": order, "count": base["count"], "total_seconds": base["total_seconds"], "tracks": ordered}"}

{"source":"def build_manifest(payload):
    if not isinstance(payload, dict):
        return sequence_playlist(payload)
    allowed = ["tracks", "order", "allow_duplicates", "title", "gap_seconds"]
    for key in sorted(payload):
        if key not in allowed:
            return {"ok": False, "error": "unexpected key '" + str(key) + "'"}
    if "title" not in payload:
        return {"ok": False, "error": "'title' is required"}
    title = payload["title"]
    if not isinstance(title, str):
        return {"ok": False, "error": "'title' must be a string"}
    clean_title = " ".join(title.split())
    if clean_title == "":
        return {"ok": False, "error": "'title' must not be blank"}
    gap = 2
    if "gap_seconds" in payload:
        gap = payload["gap_seconds"]
        if isinstance(gap, bool) or not isinstance(gap, int):
            return {"ok": False, "error": "'gap_seconds' must be an integer"}
        if gap < 0:
            return {"ok": False, "error": "'gap_seconds' must not be negative"}
    sub = {"tracks": payload["tracks"] if "tracks" in payload else None}
    if "order" in payload:
        sub["order"] = payload["order"]
    if "allow_duplicates" in payload:
        sub["allow_duplicates"] = payload["allow_duplicates"]
    seq = sequence_playlist(sub)
    if not seq["ok"]:
        return seq
    tracks = seq["tracks"]
    if seq["order"] == "artist":
        tracks = sorted(tracks, key=lambda t: (t["artist"].lower(), -t["seconds"]))
    entries = []
    position = 0
    start = 0
    total = 0
    for track in tracks:
        position = position + 1
        entries.append({"position": position, "id": track["id"], "title": track["title"], "artist": track["artist"], "seconds": track["seconds"], "clock": track["clock"], "start": start, "start_clock": format_clock(start), "explicit": track["explicit"]})
        total = total + track["seconds"]
        start = start + track["seconds"] + gap
    count = len(tracks)
    if count > 0:
        total_seconds = total + gap * (count - 1)
    else:
        total_seconds = 0
    return {"ok": True, "title": clean_title, "order": seq["order"], "count": count, "gap_seconds": gap, "total_seconds": total_seconds, "total_clock": format_clock(total_seconds), "entries": entries}"}
